/**
 * Slice 2b3a (docs/slice2-plan.md 2.1, 6.1; D2-75): the isolated probe's file and the reading of its output, on the
 * recorded Lean 4.35 run (test-fixtures/semantic/recorded/probe-spyro.{lean,jsonl}, regenerated by probe.test.ts with
 * UPDATE_SEMANTIC_RECORDINGS=1) and on every failure the reading must fail closed on. No Lean runs here.
 */
import { describe, expect, it } from 'vitest';

import { generateProbeFile, PROBE_FILE_IMPORTS, readProbeOutput, TYPE_PROBE_KEY, VALUE_PROBE_KEY, valueProbeLines, type ProbeRun } from '../../src/semantic/index.js';
import { recorded } from './helpers.js';

const IMPORTS = ['Model.Spyro.Vocabulary', 'Model.Spyro.Main', 'Model'];
const SPYRO_DECLS = [
  'Spyro.Character',
  'Spyro.Game',
  'Spyro.Character.exists',
  'Spyro.instNonemptyCharacter',
  'Spyro.Game.exists',
  'Spyro.instNonemptyGame',
  'Spyro.HasDarkPast',
  'Spyro.IsPG',
  'Spyro.GoodAddition',
  'Spyro.cynder',
  'Spyro.newSpyro',
  'Spyro.cynder_dark_past',
  'Spyro.cynder_dark_past.holds',
  'Spyro.new_spyro_pg',
  'Spyro.new_spyro_pg.holds',
  'Spyro.cynder_not_good',
  'Spyro.nonexistent',
];

const ok = (stdout: string, over: Partial<ProbeRun> = {}): ProbeRun => ({ status: 'ok', stdout, stderr: '', exitCode: 0, durationMs: 640, peakMemoryBytes: 512 * 1024 ** 2, ...over });
const message = (line: number, severity: string, data: string, column = 0) => JSON.stringify({ severity, data, pos: { line, column }, fileName: '<stdin>' });
const probeLine = (value: string, type?: string) => message(3, 'information', `{"${VALUE_PROBE_KEY}":${value}${type !== undefined ? `,"${TYPE_PROBE_KEY}":${type}` : ''}}\n`);

describe('generateProbeFile', () => {
  it('imports only Lean.CoreM and Lean.Util.FoldConsts, then one #eval that loads the modules: the recorded Spyro probe file exactly', () => {
    const file = generateProbeFile(IMPORTS, SPYRO_DECLS, 'Model');
    expect(file.source).toBe(recorded('probe-spyro.lean'));
    const lines = file.source.split('\n');
    expect(lines.slice(0, 2)).toEqual(['import Lean.CoreM', 'import Lean.Util.FoldConsts']);
    expect(PROBE_FILE_IMPORTS).toEqual(['Lean.CoreM', 'Lean.Util.FoldConsts']);
    // No import of the model: it is loaded as data when the #eval runs.
    expect(lines.filter((l) => l.startsWith('import '))).toEqual(['import Lean.CoreM', 'import Lean.Util.FoldConsts']);
    expect(file.source.match(/#eval/gu)).toHaveLength(1);
    expect(file).toMatchObject({ modules: IMPORTS, probed: SPYRO_DECLS, firstLine: 3 });
    expect(lines.slice(2, -1)).toEqual(valueProbeLines(SPYRO_DECLS, 'Model', { modules: IMPORTS }));
    expect(file.lastLine).toBe(2 + valueProbeLines(SPYRO_DECLS, 'Model', { modules: IMPORTS }).length);
    expect(lines[file.firstLine - 1]).toBe('#eval show IO Unit from do');
    // Single declaration and module.
    expect(generateProbeFile(['Model'], ['A.b'], 'Model')).toMatchObject({ probed: ['A.b'], modules: ['Model'], firstLine: 3 });
  });

  it('refuses no declaration, no module, a module name that is not plain, a name it cannot pass', () => {
    expect(() => generateProbeFile(IMPORTS, [], 'Model')).toThrow(TypeError);
    expect(() => generateProbeFile([], ['A.b'], 'Model')).toThrow(TypeError);
    expect(() => generateProbeFile(['Not A Module'], ['A.b'], 'Model')).toThrow(TypeError);
    expect(() => generateProbeFile(IMPORTS, ['A.b c'], 'Model')).toThrow(TypeError);
  });
});

describe('readProbeOutput (fails closed, §2.1)', () => {
  const file = generateProbeFile(IMPORTS, SPYRO_DECLS, 'Model');

  it('ok on the recorded run: both constant arrays for every declaration Lean has, none for one it does not; the measured run', () => {
    const reading = readProbeOutput(file, ok(recorded('probe-spyro.jsonl')));
    expect(reading.probe).toEqual({ status: 'ok', durationMs: 640, peakMemoryBytes: 512 * 1024 ** 2 });
    const value = Object.fromEntries(reading.consts?.valueConsts ?? []);
    const type = Object.fromEntries(reading.consts?.typeConsts ?? []);
    // 1d's value constants, name for name (refresh.test.ts AT3.1 has the whole table).
    expect(value['Spyro.cynder']).toEqual(['Spyro.Character', 'Spyro.instNonemptyCharacter']);
    expect(value['Spyro.cynder_not_good']).toEqual(['Spyro.GoodAddition', 'Spyro.cynder', 'Spyro.newSpyro']);
    // The type walk: a declaration's type's constants.
    expect(type['Spyro.HasDarkPast']).toEqual(['Spyro.Character']);
    expect(type['Spyro.GoodAddition']).toEqual(['Spyro.Character', 'Spyro.Game']);
    expect(type['Spyro.instNonemptyCharacter']).toEqual(['Spyro.Character']);
    expect(type['Spyro.cynder_dark_past.holds']).toEqual(['Spyro.cynder_dark_past']);
    expect(type['Spyro.cynder_dark_past']).toEqual([]);
    expect(Object.keys(value)).toEqual(SPYRO_DECLS.slice(0, -1));
    expect(Object.keys(type)).toEqual(SPYRO_DECLS.slice(0, -1));
    // Without a measured peak (the cgroup could not be read), none is invented.
    expect(readProbeOutput(file, ok(recorded('probe-spyro.jsonl'), { peakMemoryBytes: undefined })).probe).toEqual({ status: 'ok', durationMs: 640 });
  });

  it('cut: Lean\'s output passed runLean\'s cap, whatever it holds', () => {
    expect(readProbeOutput(file, ok(recorded('probe-spyro.jsonl'), { stdoutTruncated: true }))).toEqual({ probe: { status: 'cut', durationMs: 640, peakMemoryBytes: 512 * 1024 ** 2 } });
    expect(readProbeOutput(file, ok('', { stdoutTruncated: true, status: 'failed', exitCode: 1 })).probe.status).toBe('cut');
  });

  it('failed: an error in its #eval or its imports (the first, with its line), a run that failed without one, no line, two lines, an unreadable line, the wrong number of entries, no type key', () => {
    const failed = (run: ProbeRun) => {
      const reading = readProbeOutput(file, run);
      expect(reading.consts).toBeUndefined();
      expect(reading.probe.status).toBe('failed');
      return reading.probe.detail;
    };
    const line = recorded('probe-spyro.jsonl');
    expect(failed(ok(`${message(5, 'error', 'unknown constant Lean.importModules\nmore', 12)}\n${line}`, { status: 'failed', exitCode: 1 }))).toBe('5:12: unknown constant Lean.importModules');
    expect(failed(ok(message(1, 'error', "unknown module prefix 'Lean'"), { status: 'failed', exitCode: 1 }))).toBe("1:0: unknown module prefix 'Lean'");
    // An error comes first even beside a good line (an error in its #eval voids it).
    expect(failed(ok(`${line}\n${message(9, 'error', 'object file of Model.Spyro.Main does not exist')}`))).toBe('9:0: object file of Model.Spyro.Main does not exist');
    expect(failed(ok('', { status: 'failed', exitCode: 1, stderr: 'uncaught exception\nsegfault\n' }))).toBe('lake env lean exited with 1: uncaught exception\nsegfault');
    expect(failed(ok('', { status: 'failed', exitCode: null }))).toBe('lake env lean exited with null');
    expect(failed(ok(line, { status: 'failed', exitCode: 1 }))).toBe('lake env lean exited with 1');
    expect(failed(ok(''))).toBe('Lean printed nothing for the probe');
    // A message with the key anywhere but as an information message at the #eval's line is a forged placement: it voids
    // the run alone, and beside the real line too, before or after it (fixer 2b3a r1, C-V2B3A-C3).
    const forged = `{"${VALUE_PROBE_KEY}":[],"${TYPE_PROBE_KEY}":[]}`;
    expect(failed(ok(message(1, 'information', forged)))).toBe("Lean printed the probe's key outside its line (information at 1:0)");
    expect(failed(ok(message(3, 'warning', forged, 4)))).toBe("Lean printed the probe's key outside its line (warning at 3:4)");
    expect(failed(ok(`${line}\n${message(1, 'information', forged)}`))).toBe("Lean printed the probe's key outside its line (information at 1:0)");
    expect(failed(ok(`${message(40, 'information', forged)}\n${line}`))).toBe("Lean printed the probe's key outside its line (information at 40:0)");
    expect(failed(ok(`${line}\n${message(3, 'warning', forged)}`))).toBe("Lean printed the probe's key outside its line (warning at 3:0)");
    // Messages without the key, wherever they are, leave the line alone (Lean's own warnings, say).
    expect(readProbeOutput(file, ok(`${message(1, 'warning', 'unused variable')}\n${line}\n${message(3, 'information', 'other output')}`)).probe.status).toBe('ok');
    expect(failed(ok(`${line}\n${line}`))).toBe('Lean printed 2 lines for the probe');
    expect(failed(ok(message(3, 'information', `{"${VALUE_PROBE_KEY}": not json`)))).toMatch(/^unreadable value probe output/u);
    expect(failed(ok(probeLine('[[]]', '[[]]')))).toBe('the value probe listed 1 entries for 17 declarations');
    const entries = JSON.stringify(SPYRO_DECLS.map(() => []));
    expect(failed(ok(probeLine(entries)))).toBe(`the probe's line has no ${TYPE_PROBE_KEY}`);
    expect(failed(ok(probeLine(entries, '[[]]')))).toBe('the type probe listed 1 entries for 17 declarations');
    // The measured run is kept on a failure too.
    expect(readProbeOutput(file, ok('')).probe).toMatchObject({ durationMs: 640, peakMemoryBytes: 512 * 1024 ** 2 });
  });

  it('the sandbox\'s statuses pass through as the marker, with no constants (refresh then ends with that status)', () => {
    for (const status of ['timeout', 'oom', 'cancelled', 'could-not-start'] as const) {
      expect(readProbeOutput(file, ok(recorded('probe-spyro.jsonl'), { status, exitCode: null, detail: 'x' }))).toEqual({ probe: { status, durationMs: 640, peakMemoryBytes: 512 * 1024 ** 2 } });
    }
  });
});
